import './style.css';
import * as THREE from 'three';

const mount = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x081310);
scene.fog = new THREE.FogExp2(0x14271f, 0.0085);
const camera = new THREE.PerspectiveCamera(43, innerWidth / innerHeight, 0.1, 180);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.15;
mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc5e4ff, 0x25391b, 1.8));
const keyLight = new THREE.DirectionalLight(0xffefcf, 3.2); keyLight.position.set(-11, 24, 13); keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024); keyLight.shadow.camera.left = -27; keyLight.shadow.camera.right = 27; keyLight.shadow.camera.top = 24; keyLight.shadow.camera.bottom = -24; keyLight.shadow.bias = -0.0004; scene.add(keyLight);
for (const [x,z] of [[-18,-5],[18,-5],[-18,9],[18,9]]) { const l=new THREE.SpotLight(0xe4efff, 220, 48, Math.PI/5, .5, 1.4); l.position.set(x,19,z); l.target.position.set(x*.35,0,z*.4); scene.add(l,l.target); }
const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const grassMat=mat(0x3c773e,1), white=mat(0xe9ebde,.65), dark=mat(0x101915), crowdMats=[0x304b42,0x56675a,0x9a402e,0xd7d1b3,0x37536c,0x9aa14a,0x6a3641,0x222e29,0xc0c4b8].map(c=>mat(c));
