const keys=new Set();let joy={x:0,y:0},sprinting=false,gameState='intro',started=false,clock=0,scoreHome=0,scoreAway=0,elapsed=0,timeScale=1,slowTimer=0,shot=null,owner='hero',possessionTimer=0,dialogueTimer=0,cameraMode='intro',cameraBlend=0;
const ui={intro:document.querySelector('#intro'),start:document.querySelector('#startBtn'),score:document.querySelector('#scoreboard'),clock:document.querySelector('#gameClock'),home:document.querySelector('#homeScore'),away:document.querySelector('#awayScore'),status:document.querySelector('#matchStatus'),objective:document.querySelector('#objective'),dialogue:document.querySelector('#dialogue'),dialogueText:document.querySelector('#dialogueText'),hint:document.querySelector('#skillHint'),controls:document.querySelector('#controlsHint'),touch:document.querySelector('#touchControls'),end:document.querySelector('#endScreen'),endTitle:document.querySelector('#endTitle'),endCopy:document.querySelector('#endCopy'),letterboxes:[...document.querySelectorAll('.letterbox')]};
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Space'&&!e.repeat)performSombrero();if(e.code==='KeyF'&&!e.repeat)shootBall();if(e.code.startsWith('Shift'))sprinting=true;});window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code.startsWith('Shift'))sprinting=false;});
const joyBase=document.querySelector('#joystick'),joyKnob=document.querySelector('#joyKnob');let joyPointer=null;joyBase.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joyBase.setPointerCapture(e.pointerId);updateJoy(e);});joyBase.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)updateJoy(e);});function updateJoy(e){const r=joyBase.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),scale=Math.min(1,35/(len||1));joy.x=dx/35*scale;joy.y=dy/35*scale;joyKnob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}function releaseJoy(e){if(e.pointerId!==joyPointer)return;joyPointer=null;joy.x=joy.y=0;joyKnob.style.transform='translate(0,0)';}joyBase.addEventListener('pointerup',releaseJoy);joyBase.addEventListener('pointercancel',releaseJoy);
