let audio=null,ambientGain=null,audioEnabled=true;function initAudio(){if(audio)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audio=new AC();const length=audio.sampleRate*2,buffer=audio.createBuffer(1,length,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(.35+Math.sin(i/length*Math.PI*2)*.24);const noise=audio.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audio.createBiquadFilter();filter.type='bandpass';filter.frequency.value=720;filter.Q.value=.55;ambientGain=audio.createGain();ambientGain.gain.value=.075;noise.connect(filter).connect(ambientGain).connect(audio.destination);noise.start();audio.resume();}
function tone(freq,duration,type='sine',volume=.1,delay=0){if(!audio||!audioEnabled)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,audio.currentTime+delay);g.gain.exponentialRampToValueAtTime(volume,audio.currentTime+delay+.025);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+delay+duration);o.connect(g).connect(audio.destination);o.start(audio.currentTime+delay);o.stop(audio.currentTime+delay+duration+.04);}function sfx(kind){if(!audio||!audioEnabled)return;if(kind==='kick'){tone(105,.14,'sine',.28);tone(48,.17,'triangle',.24,.015);tone(620,.045,'triangle',.09,.01);}if(kind==='whistle'){tone(1700,.27,'sine',.07);tone(2140,.32,'sine',.06,.08);}if(kind==='crowd'){tone(90,.7,'sawtooth',.055);tone(130,.6,'sine',.06,.04);tone(185,.52,'triangle',.035,.13);tone(270,.4,'sine',.025,.18);}if(kind==='skill'){tone(700,.3,'sine',.07);tone(990,.4,'sine',.06,.1);tone(1250,.55,'sine',.04,.2);}if(kind==='goal'){for(let i=0;i<7;i++)tone(160+i*65,.9,'sawtooth',.035,i*.045);}}

