function say(text,tag='NARRAÇÃO',duration=3.3){ui.dialogueText.textContent=text;ui.dialogue.querySelector('.dialogue-tag').textContent=tag;ui.dialogue.classList.add('show');dialogueTimer=duration;}
let matchStart=0;function beginGame(){if(started)return;started=true;initAudio();sfx('whistle');gameState='cinematic';cameraMode='intro';ui.intro.classList.add('hidden');ui.score.classList.add('visible');ui.status.classList.add('visible');ui.status.textContent='APRESENTAÇÃO';ui.touch.style.display='flex';ui.objective.style.opacity='0';ui.letterboxes.forEach(x=>x.classList.add('active'));matchStart=performance.now();say('A Vila está de pé. É noite de decisão.','NARRADOR',3.3);setTimeout(()=>{if(gameState==='cinematic')say('Neymar: essa é pela minha família.','NEYMAR JR.',3);},2200);setTimeout(()=>{if(gameState==='cinematic'){gameState='play';cameraMode='follow';clock=0;ui.status.textContent='1º TEMPO';ui.objective.style.opacity='1';ui.letterboxes.forEach(x=>x.classList.remove('active'));say('Vai pra cima, Ney! O gol é seu.','NARRADOR',3.5);}},4800);}
ui.start.addEventListener('click',beginGame);document.querySelector('#againBtn').addEventListener('click',()=>location.reload());const soundToggle=document.querySelector('#soundToggle');soundToggle.addEventListener('click',()=>{audioEnabled=!audioEnabled;if(audioEnabled){initAudio();ambientGain&&(ambientGain.gain.value=.075);}else if(ambientGain)ambientGain.gain.value=0;soundToggle.innerHTML=audioEnabled?'♫ <span>SOM</span>':'♪ <span>MUDO</span>';});
function performSombrero(){if(gameState!=='play'||!started||shot)return;const d=neymar.root.position.distanceTo(rival.root.position),bd=ball.position.distanceTo(neymar.root.position);if(d>6.2||bd>2.25){say(d>6.2?'Aproxime-se do rival para tentar o chapéu!':'Recupere a bola primeiro.','DICA',2);return;}gameState='sombrero';slowTimer=2.15;timeScale=.17;cameraMode='skill';const dir=new THREE.Vector3(0,0,-1).applyQuaternion(neymar.root.quaternion);neymar.velocity.copy(dir).multiplyScalar(5);ball.position.set(neymar.root.position.x,.35,neymar.root.position.z-.2);ball.userData.arc=1.5;ball.userData.arcTime=0;owner='loose';rival.userData.stun=1.6;ui.status.textContent='CHAPÉU!';ui.status.style.color='#efff69';say('QUE CHAPÉU! O estádio inteiro levantou!','NARRADOR',3.1);sfx('skill');setTimeout(()=>{if(gameState==='sombrero'){gameState='play';timeScale=1;cameraMode='follow';ui.status.textContent='1º TEMPO';}},1550);}
function shootBall(){if(gameState!=='play'||!started||shot)return;const d=ball.position.distanceTo(neymar.root.position);if(owner!=='hero'&&d>1.45){say('Chegue mais perto da bola para finalizar.','DICA',1.8);return;}let dir=new THREE.Vector3(0,0,-1).applyQuaternion(neymar.root.quaternion);if(dir.z>-.25)dir.set(0,0,-1);dir.normalize();shot={velocity:dir.multiplyScalar(sprinting?15:12),timer:0};owner='loose';ball.position.y=.23;sfx('kick');neymar.velocity.addScaledVector(shot.velocity,.055);ui.status.textContent='FINALIZAÇÃO!';}
function resetPositions(){neymar.root.position.set(-1.3,0,4);neymar.root.rotation.y=0;neymar.velocity.set(0,0,0);rival.root.position.set(.9,0,-.9);rival.root.rotation.y=Math.PI;rival.velocity.set(0,0,0);ball.position.set(-1.3,.22,2.95);ball.userData.arc=0;ball.userData.arcTime=0;owner='hero';possessionTimer=0;shot=null;}
function showEnd(won){gameState='end';timeScale=1;ui.end.classList.remove('hidden');ui.endTitle.textContent=won?'É NOSSA!':'FIM DE JOGO';ui.endCopy.textContent=won?'Neymar corre até Mavi e o pai dela. “Eu fiz isso por vocês.”':'O apito final soou. A rivalidade continua…';sfx(won?'goal':'whistle');say(won?'Neymar: eu fiz tudo isso por vocês.':'Que confronto. O estádio aplaude os dois.',won?'NEYMAR JR.':'NARRADOR',5);}
function goal(who){if(gameState!=='play')return;gameState='celebration';if(who==='hero'){scoreHome++;ui.home.textContent=scoreHome;sfx('goal');ui.status.textContent='GOOOOL DO NEYMAR!';ui.status.style.color='#efff69';say('GOOOOL! Neymar fez história! É por ela!','NARRADOR',3.3);cameraMode='goal';cameraBlend=2.8;}else{scoreAway++;ui.away.textContent=scoreAway;sfx('goal');ui.status.textContent='GOL DO RIVAL';say('O rival responde. Ainda dá tempo!','NARRADOR',2.8);cameraMode='goalAway';cameraBlend=2.2;}shot=null;owner='loose';setTimeout(()=>{if(gameState==='celebration'){if(scoreHome>=2){showEnd(true);return;}if(scoreAway>=2){showEnd(false);return;}resetPositions();gameState='play';cameraMode='follow';ui.status.textContent='1º TEMPO';ui.status.style.color='#dcef43';}},2450);}

