function update(dt,realElapsed){elapsed=realElapsed;const effective=dt*timeScale;
 if(gameState==='cinematic'){const a=realElapsed*.42;camera.position.lerp(new THREE.Vector3(Math.sin(a)*8,5.5,Math.cos(a)*8+1),.025);camera.lookAt(0,1,0);neymar.root.rotation.y=Math.sin(realElapsed*.4)*.08;rival.root.rotation.y=Math.PI+Math.sin(realElapsed*.45)*.08;animateRig(neymar,realElapsed);animateRig(rival,realElapsed);ball.rotation.x+=dt*1.1;}
 if(gameState==='play'||gameState==='sombrero'){
