  const move=new THREE.Vector3((keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+joy.x,0,(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+joy.y);if(move.lengthSq()>1)move.normalize();if(active)updatePlayer(neymar,effective,move,sprinting,realElapsed);else{neymar.root.position.addScaledVector(neymar.velocity,effective);neymar.velocity.multiplyScalar(Math.max(0,1-effective*1.4));neymar.root.position.x=THREE.MathUtils.clamp(neymar.root.position.x,-19,19);}

