  if(owner==='hero'||owner==='rival){const carrier=owner==='hero'?neymar:rival,forward=new THREE.Vector3(0,0,-1).applyQuaternion(carrier.root.quaternion),dribble=carrier.root.position.clone().addScaledVector(forward,.87);dribble.y=.22+Math.abs(Math.sin(realElapsed*9))*.065*Math.min(1,carrier.speed/3);ball.position.lerp(dribble,Math.min(1,effective*12));ball.rotation.x+=carrier.speed*effective*1.6;ball.rotation.z+=carrier.speed*effective*.6;possessionTimer+=dt;
