   if(owner==='rival'&&rival.root.position.z>7&&possessionTimer>1.3){shot={velocity:new THREE.Vector3(0,0,1).multiplyScalar(10),timer:0};owner='loose';possessionTimer=0;sfx('kick');}
  }else if(shot){ball.position.addScaledVector(shot.velocity,effective);shot.velocity.multiplyScalar(Math.max(0,1-effective*.3));shot.timer+=dt;ball.rotation.x+=effective*9;ball.rotation.z+=effective*4;if(ball.position.z< -13.28&&Math.abs(ball.position.x)<3.55){goal('hero');return;}if(ball.position.z>13.28&&Math.abs(ball.position.x)<3.55){goal('rival');return;}if(shot.timer>2.1||Math.abs(ball.position.x)>22||Math.abs(ball.position.z)>15){shot=null;ball.position.y=.23;}}
