 function performSombrero(){if(gameState!=='play'||!started||shot)return;const d=neymar.root.position.distanceTo(rival.root.position),bd=ball.position.distanceTo(neymar.root.position);if(d>6.2||bd>2.25){say(d>6.2?'Aproxime-se do rival para tentar o chapéu!':'Recupere a bola primeiro.','DICA',2);return;}gameState='sombrero';slowTimer=2.15;timeScale=.17;cameraMode='skill';const dir=new THREE.Vector3(0,0,-1).applyQuaternion(neymar.root.quaternion);neymar.velocity.copy(dir).multiplyScalar(5);ball.position.set(neymar.root.position.x,.35,neymar.root.position.z-.2);ball.userData.arc=1.5;ball.userData.arcTime=0;owner='loose';rival.userData.stun=1.6;ui.status.textContent='CHAPÉU!';ui.status.style.color='#efff69';say('QUE CHAPÉU! O estádio inteiro levantou!','NARRADOR',3.1);sfx('skill');setTimeout(()=>{if(gameState==='sombrero'){gameState='play';timeScale=1;cameraMode='follow';ui.status.textContent='1º TEMPO';}},1550);}
